public class UTF8JsonGeneratorTest{
private static final String TEST_STR = "{\"test\":\"test\"}";
  private static final String TEST_STR2 = "{\"test\":123}";
  private static final String TEST_STR3 = "{\"test\":123.456}";
  private static final String TEST_STR4 = "{\"test\":null}";
  private static final String TEST_STR5 = "{\"test\":true}";
  private static final String TEST_STR6 = "{\"test\":false}";
  private static final String TEST_STR7 = "{\"test\":[1,2,3]}";
  private static final String TEST_STR8 = "{\"test\":{\"a\":1,\"b\":2}}";

  private ByteArrayOutputStream baos;
  private UTF8JsonGenerator generator;

  @Before
  public void before(){
    baos = new ByteArrayOutputStream();
    generator = new UTF8JsonGenerator(new IOContext(new Object(),true), JsonGenerator.Feature.autoCloseTarget, null, baos);
  }

  @After
  public void after(){
    baos = null;
    generator = null;
  }

  @Test
  public void testWriteNumberBigDecimal() throws IOException{
    BigDecimal bd = new BigDecimal("123.456");
    generator.writeStartObject();
    generator.writeNumberField("test",bd);
    generator.writeEndObject();
    generator.flush();
    String result = baos.toString();
    assertThat(result, is(equalTo(TEST_STR3)));
  }

  @Test
  public void testWriteNumberBigDecimalNull() throws IOException{
    generator.writeStartObject();
    generator.writeNumberField("test",null);
    generator.writeEndObject();
    generator.flush();
    String result = baos.toString();
    assertThat(result, is(equalTo(TEST_STR4)));
  }

  @Test
  public void testWriteNumberBigDecimalAsString() throws IOException{
    generator = new UTF8JsonGenerator(new IOContext(new Object(),true), JsonGenerator.Feature.autoCloseTarget|JsonGenerator.Feature.QUOTE_FIELD_NAMES, null, baos);
    generator.enable(JsonGenerator.Feature.QUOTE_STRING_NUMBERS);
    BigDecimal bd = new BigDecimal("123.456");
    generator.writeStartObject();
    generator.writeNumberField("test",bd);
    generator.writeEndObject();
    generator.flush();
    String result = baos.toString();
    assertThat(result, is(equalTo(TEST_STR2)));
  }

  @Test(expected = IOException.class)
  public void testWriteNumberBigDecimalIOException() throws IOException{
    generator = spy(generator);
    doThrow(new IOException()).when(generator).writeRaw(anyString());
    BigDecimal bd = new BigDecimal("123.456");
    generator.writeStartObject();
    generator.writeNumberField("test",bd);
    generator.writeEndObject();
  }
}
