@Test
    public void testGetValueAsString() throws Exception{
        JsonToken[] tokens = new JsonToken[]{JsonToken.VALUE_STRING, JsonToken.FIELD_NAME};
        String[] expected = new String[]{"test", "test"};
        for(int i=0; i<tokens.length; i++){
            bais = new ByteArrayInputStream(getUtf8Bytes(getUtf8String(tokens[i])));
            parser = new UTF8StreamJsonParser(context, JsonParser.Feature.ALLOW_UNQUOTED_STRINGS.enabled, bais, null, null, null, 0, 0, true);
            parser.nextToken();
            parser._currToken = tokens[i];
            if(tokens[i] == JsonToken.VALUE_STRING){
                String result = parser.getValueAsString("default");
                Assert.assertEquals(expected[i], result);
            }else if(tokens[i] == JsonToken.FIELD_NAME){
